// index.js  -  Contestador de WhatsApp con la Cloud API oficial de Meta
// Necesitas Node.js 18 o superior (trae fetch de serie).
//
// En la terminal, dentro de una carpeta vacia:
//   npm init -y
//   npm install express
//   node index.js
//
// Las tres variables de abajo NO se escriben aqui dentro. Se ponen fuera:
//   en Windows PowerShell:  $env:WHATSAPP_TOKEN="EAAG..."
//   en Railway o Render:    pestaña "Variables" / "Environment"

const express = require('express');
const app = express();
app.use(express.json());

const TOKEN         = process.env.WHATSAPP_TOKEN;   // token permanente del usuario del sistema
const PHONE_ID      = process.env.PHONE_NUMBER_ID;  // "Phone number ID", NO el numero de telefono
const VERIFY_TOKEN  = process.env.VERIFY_TOKEN;     // una frase que te inventas tu, la misma que pegas en Meta

// ---------------------------------------------------------------
// 1) Meta llama aqui UNA sola vez, para comprobar que la URL es tuya
// ---------------------------------------------------------------
app.get('/webhook', (req, res) => {
  const mode      = req.query['hub.mode'];
  const token     = req.query['hub.verify_token'];
  const challenge = req.query['hub.challenge'];

  if (mode === 'subscribe' && token === VERIFY_TOKEN) {
    console.log('Meta ha verificado el webhook. Bien.');
    return res.status(200).send(challenge);
  }
  console.error('Verificacion fallida: el verify token no coincide.');
  return res.sendStatus(403);
});

// ---------------------------------------------------------------
// 2) Aqui aterriza cada mensaje que te manda un cliente
// ---------------------------------------------------------------
app.post('/webhook', async (req, res) => {
  res.sendStatus(200);   // contesta YA. Si tardas, Meta reintenta y el cliente recibe todo doble.

  try {
    const value = req.body
      && req.body.entry && req.body.entry[0]
      && req.body.entry[0].changes && req.body.entry[0].changes[0]
      && req.body.entry[0].changes[0].value;

    const msg = value && value.messages && value.messages[0];
    if (!msg) return;    // no era un mensaje: era un aviso de "entregado" o "leido"

    const de = msg.from; // numero del cliente, con prefijo y sin +

    if (msg.type !== 'text') {
      await enviarTexto(de, 'De momento solo entiendo texto. Escríbeme tu pregunta.');
      return;
    }

    const respuesta = await pensar(msg.text.body);
    await enviarTexto(de, respuesta);

  } catch (e) {
    console.error('Fallo procesando el mensaje:', e);
  }
});

// ---------------------------------------------------------------
// 3) Responder dentro de la ventana de 24 h: texto libre y gratis
// ---------------------------------------------------------------
async function enviarTexto(para, texto) {
  const url = 'https://graph.facebook.com/v21.0/' + PHONE_ID + '/messages';

  const r = await fetch(url, {
    method: 'POST',
    headers: {
      'Authorization': 'Bearer ' + TOKEN,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      messaging_product: 'whatsapp',
      to: para,
      type: 'text',
      text: { body: texto.slice(0, 4000) }   // el limite real son 4096 caracteres
    })
  });

  if (!r.ok) {
    // Aqui es donde veras el (#131047) si se te ha cerrado la ventana de 24 h
    console.error('WhatsApp ha dicho que no:', r.status, await r.text());
  }
}

// ---------------------------------------------------------------
// 4) Lo que contesta. Cambia esto por una llamada a la IA que uses.
// ---------------------------------------------------------------
async function pensar(texto) {
  const t = texto.toLowerCase();
  if (t.includes('horario') || t.includes('abierto')) return 'Abrimos de 9:00 a 18:00, de lunes a viernes.';
  if (t.includes('precio') || t.includes('cuesta'))   return 'Tienes los precios aquí: https://TU-WEB.com/precios';
  if (t.includes('pedido'))                            return 'Dime tu número de pedido y te digo por dónde va.';
  return 'Hola, soy el asistente de [TU NEGOCIO]. Pregúntame por horario, precios o pedidos.';
}

app.listen(3000, () => console.log('Escuchando en el puerto 3000. Falta exponerlo a internet.'));

